// Runtime application schema for database initialization.
export const sqliteSchema: string[] = ["PRAGMA foreign_keys = ON;\nCREATE TABLE IF NOT EXISTS officials (\n id TEXT PRIMARY KEY, name TEXT NOT NULL, designation TEXT NOT NULL, bureau TEXT NOT NULL,\n role TEXT NOT NULL CHECK(role IN ('official','manager','it')), manager_id TEXT REFERENCES officials(id),\n is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1)), active INTEGER NOT NULL DEFAULT 1,\n password_hash TEXT, password_salt TEXT\n);\nCREATE INDEX IF NOT EXISTS officials_manager ON officials(manager_id, is_demo);\nCREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, official_id TEXT NOT NULL REFERENCES officials(id), expires_at INTEGER NOT NULL);\nCREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);\nCREATE TABLE IF NOT EXISTS institutions (\n id TEXT PRIMARY KEY, name TEXT NOT NULL, permanent_id TEXT NOT NULL UNIQUE, city TEXT NOT NULL,\n state TEXT NOT NULL, region TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1))\n);\nCREATE INDEX IF NOT EXISTS institution_search ON institutions(is_demo,name);\nCREATE TABLE IF NOT EXISTS tags (code TEXT PRIMARY KEY, label TEXT NOT NULL, group_name TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS cases (\n id TEXT PRIMARY KEY, subject TEXT NOT NULL, institution_id TEXT NOT NULL REFERENCES institutions(id),\n bureau TEXT NOT NULL, assigned_to TEXT NOT NULL REFERENCES officials(id), created_by TEXT NOT NULL REFERENCES officials(id),\n status TEXT NOT NULL CHECK(status IN ('Pending','Under process','Awaiting information','Disposed')),\n intake TEXT NOT NULL CHECK(intake IN ('Submitted','Approved','Returned','Rejected')),\n escalated INTEGER NOT NULL DEFAULT 0, priority TEXT NOT NULL DEFAULT 'Routine', tags TEXT NOT NULL DEFAULT '[]',\n description TEXT NOT NULL, next_action TEXT NOT NULL, received_at TEXT NOT NULL, due_at TEXT NOT NULL,\n updated_at TEXT NOT NULL, is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1)), approval_reason TEXT NOT NULL DEFAULT ''\n);\nCREATE INDEX IF NOT EXISTS cases_assigned ON cases(is_demo,assigned_to,intake,updated_at DESC,id);\nCREATE INDEX IF NOT EXISTS cases_institution ON cases(is_demo,institution_id,intake,status);\nCREATE INDEX IF NOT EXISTS cases_created ON cases(is_demo,created_by,intake);\nCREATE INDEX IF NOT EXISTS cases_bureau ON cases(is_demo,bureau,intake,updated_at DESC);\nCREATE TABLE IF NOT EXISTS case_events (\n id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), kind TEXT NOT NULL,\n actor_id TEXT NOT NULL REFERENCES officials(id), body TEXT NOT NULL, created_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS events_case ON case_events(case_id,created_at,id);\nCREATE TRIGGER IF NOT EXISTS immutable_events_update BEFORE UPDATE ON case_events BEGIN SELECT RAISE(ABORT,'Case history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS immutable_events_delete BEFORE DELETE ON case_events BEGIN SELECT RAISE(ABORT,'Case history is append-only'); END;\nCREATE TABLE IF NOT EXISTS case_grants (\n case_id TEXT NOT NULL REFERENCES cases(id), official_id TEXT NOT NULL REFERENCES officials(id),\n granted_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY(case_id,official_id)\n);\nCREATE INDEX IF NOT EXISTS grants_official ON case_grants(official_id,revoked_at,case_id);\nCREATE TABLE IF NOT EXISTS coordination_requests (\n id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id), requester_id TEXT NOT NULL REFERENCES officials(id),\n target_official_id TEXT NOT NULL REFERENCES officials(id), target_bureau TEXT NOT NULL,\n status TEXT NOT NULL CHECK(status IN ('Awaiting manager','Awaiting Bureau','Approved','Rejected','Revoked')),\n reason TEXT NOT NULL, manager_approved_at TEXT, bureau_approved_at TEXT, created_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS coordination_case ON coordination_requests(case_id,created_at);\nCREATE INDEX IF NOT EXISTS coordination_target ON coordination_requests(target_official_id,status);\nCREATE UNIQUE INDEX IF NOT EXISTS coordination_open ON coordination_requests(case_id,target_official_id) WHERE status IN ('Awaiting manager','Awaiting Bureau','Approved');\nCREATE TABLE IF NOT EXISTS messages (\n id TEXT PRIMARY KEY, sender_id TEXT NOT NULL REFERENCES officials(id), recipient_id TEXT NOT NULL REFERENCES officials(id),\n case_id TEXT REFERENCES cases(id), body TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT,\n is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1))\n);\nCREATE INDEX IF NOT EXISTS messages_recipient ON messages(is_demo,recipient_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS messages_sender ON messages(is_demo,sender_id,created_at DESC);\n", "CREATE TABLE IF NOT EXISTS workspace_settings (\n is_demo INTEGER PRIMARY KEY CHECK(is_demo IN(0,1)), support_email TEXT NOT NULL DEFAULT '',\n sender_email TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES officials(id)\n);\nCREATE TABLE IF NOT EXISTS tag_cache (\n cache_key TEXT PRIMARY KEY, suggestions TEXT NOT NULL, expires_at INTEGER NOT NULL\n);\nCREATE INDEX IF NOT EXISTS tag_cache_expiry ON tag_cache(expires_at);\nCREATE TABLE IF NOT EXISTS inference_usage (\n official_id TEXT NOT NULL REFERENCES officials(id), day TEXT NOT NULL, calls INTEGER NOT NULL DEFAULT 0,\n PRIMARY KEY(official_id,day)\n);\n", "ALTER TABLE sessions ADD COLUMN portal TEXT NOT NULL DEFAULT 'official' CHECK(portal IN('official','it'));\nCREATE TABLE IF NOT EXISTS migration_settings (\n is_demo INTEGER PRIMARY KEY CHECK(is_demo IN(0,1)), host TEXT NOT NULL DEFAULT '',\n port INTEGER NOT NULL DEFAULT 5432, database_name TEXT NOT NULL DEFAULT '', username TEXT NOT NULL DEFAULT '',\n ssl_mode TEXT NOT NULL DEFAULT 'verify-full', updated_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES officials(id)\n);\n", "ALTER TABLE migration_settings ADD COLUMN source TEXT NOT NULL DEFAULT 'postgres' CHECK(source IN('d1','postgres'));\nALTER TABLE migration_settings ADD COLUMN d1_database_id TEXT NOT NULL DEFAULT '';\n", "CREATE VIRTUAL TABLE official_search USING fts5(name,id,designation,bureau,content='officials',content_rowid='rowid',tokenize='unicode61');\nINSERT INTO official_search(official_search) VALUES('rebuild');\nCREATE TRIGGER official_search_insert AFTER INSERT ON officials BEGIN\n INSERT INTO official_search(rowid,name,id,designation,bureau) VALUES(new.rowid,new.name,new.id,new.designation,new.bureau);\nEND;\nCREATE TRIGGER official_search_delete AFTER DELETE ON officials BEGIN\n INSERT INTO official_search(official_search,rowid,name,id,designation,bureau) VALUES('delete',old.rowid,old.name,old.id,old.designation,old.bureau);\nEND;\nCREATE TRIGGER official_search_update AFTER UPDATE OF name,id,designation,bureau ON officials BEGIN\n INSERT INTO official_search(official_search,rowid,name,id,designation,bureau) VALUES('delete',old.rowid,old.name,old.id,old.designation,old.bureau);\n INSERT INTO official_search(rowid,name,id,designation,bureau) VALUES(new.rowid,new.name,new.id,new.designation,new.bureau);\nEND;\n", "CREATE TABLE org_units(code TEXT PRIMARY KEY,name TEXT NOT NULL,unit_type TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,verification TEXT NOT NULL DEFAULT 'unverified',source TEXT NOT NULL DEFAULT 'Reference/AICTE_Dashboard_Reference_Spec.md');\nALTER TABLE tags ADD COLUMN active INTEGER NOT NULL DEFAULT 1;\nALTER TABLE tags ADD COLUMN source TEXT NOT NULL DEFAULT 'Reference/AICTE_Dashboard_Reference_Spec.md';\nINSERT INTO org_units(code,name,unit_type) VALUES('RB','Regulation Bureau','Bureau');\nINSERT INTO org_units(code,name,unit_type) VALUES('ADMIN','Administration Bureau','Bureau');\nINSERT INTO org_units(code,name,unit_type) VALUES('FIN','Finance Bureau','Bureau');\nINSERT INTO org_units(code,name,unit_type) VALUES('PAP','Policy & Academic Planning','Bureau');\nINSERT INTO org_units(code,name,unit_type) VALUES('ATAL','Training & Learning / ATAL','Programme');\nINSERT INTO org_units(code,name,unit_type) VALUES('SCH_GRANTS','Scholarships & Grants','Programme');\nINSERT INTO org_units(code,name,unit_type) VALUES('PGRC','Public Grievance Redressal Cell','Cell');\nINSERT INTO org_units(code,name,unit_type) VALUES('VIGILANCE','Vigilance Cell','Cell');\nINSERT INTO org_units(code,name,unit_type) VALUES('SKILL','Skill Development Cell','Cell');\nINSERT INTO org_units(code,name,unit_type) VALUES('NEAT','National Educational Alliance for Technology Cell','Cell');\nINSERT INTO org_units(code,name,unit_type) VALUES('CYBER','Cyber Security Cell / CISO Office','Cell');\nINSERT INTO org_units(code,name,unit_type) VALUES('IKS','Indian Knowledge Systems Cell','Cell');\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('ADM_MERIT','Admission merit violation','Admission & Prospectus',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('ADM_PROCESS','Admission-process irregularity','Admission & Prospectus',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('ADM_REFUSAL','Improper refusal of admission','Admission & Prospectus',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('PROSPECTUS_MISSING','Prospectus not published','Admission & Prospectus',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('PROSPECTUS_MISLEADING','False or misleading prospectus','Admission & Prospectus',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('DOC_WITHHELD','Original certificates/documents withheld','Financial & Documents',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('FEE_EXCESS','Fees demanded beyond declared policy','Financial & Documents',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('SCHOLARSHIP_DELAY','Scholarship / financial-aid delay or nonpayment','Financial & Documents',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('FEE_REFUND','Fee refund refused or delayed','Financial & Documents',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('RESERVATION','Reservation-policy violation','Admission & Equity',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('DISCRIMINATION','Discrimination','Discrimination & Harassment',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('HARASSMENT','Harassment or victimization','Discrimination & Harassment',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('EXAM_DELAY','Examination delay','Academic',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('RESULT_DELAY','Result publication delay','Academic',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('UNFAIR_EVALUATION','Unfair evaluation practice','Academic',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('EDUCATION_QUALITY','Promised education quality not delivered','Academic',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('AMENITIES','Inadequate student amenities','Academic & Infrastructure',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('APPROVAL_IRREGULARITY','Approval/extension irregularity','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('UNAPPROVED_COURSE','Unapproved course or programme','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('INTAKE_NONCOMPLIANCE','Approved-intake noncompliance','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('INFRASTRUCTURE_DEFICIT','Infrastructure or laboratory deficiency','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('FACULTY_SHORTAGE','Faculty shortage / qualification deficiency','Faculty & Staffing',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('FACULTY_SERVICE','Faculty employment or service grievance','Faculty & Staffing',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('STAFF_SERVICE','Non-teaching staff service grievance','Faculty & Staffing',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('SALARY_NONPAYMENT','Salary or remuneration nonpayment','Faculty & Staffing',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('SAFETY','Campus safety concern','Institutional Welfare',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('ANTI_RAGGING','Ragging-related institutional compliance','Institutional Welfare',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('ACCESSIBILITY','Accessibility concern','Institutional Welfare',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('RECORDS_MISREPORT','Misrepresentation of institutional records','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('FINANCIAL_MALPRACTICE','Institutional financial malpractice','Regulatory',1);\nINSERT OR REPLACE INTO tags(code,label,group_name,active) VALUES('OTHER','Other / requires classification','General',1);\nUPDATE cases SET tags=(SELECT json_group_array(CASE value WHEN 'fees' THEN 'FEE_EXCESS' WHEN 'refund' THEN 'FEE_REFUND' WHEN 'approval' THEN 'APPROVAL_IRREGULARITY' WHEN 'faculty' THEN 'FACULTY_SHORTAGE' WHEN 'facilities' THEN 'INFRASTRUCTURE_DEFICIT' WHEN 'admission' THEN 'ADM_PROCESS' ELSE value END) FROM json_each(cases.tags));\nUPDATE tags SET active=0 WHERE code IN('fees','refund','approval','faculty','facilities','admission');\nUPDATE officials SET bureau=CASE bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE bureau END;\nUPDATE cases SET bureau=CASE bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE bureau END;\nUPDATE coordination_requests SET target_bureau=CASE target_bureau WHEN 'Regulation' THEN 'RB' WHEN 'Grievance' THEN 'PGRC' ELSE target_bureau END;\nUPDATE institutions SET region=CASE region WHEN 'West' THEN 'Western' WHEN 'South' THEN 'Southern' WHEN 'North' THEN 'Northern' ELSE region END;\n", "CREATE TABLE case_relations (\n case_id TEXT NOT NULL REFERENCES cases(id),related_case_id TEXT NOT NULL REFERENCES cases(id),\n kind TEXT NOT NULL CHECK(kind IN('Related','Duplicate','Unrelated')),reason TEXT NOT NULL,\n created_by TEXT NOT NULL REFERENCES officials(id),created_at TEXT NOT NULL,\n PRIMARY KEY(case_id,related_case_id),CHECK(case_id<related_case_id)\n);\nCREATE INDEX relations_other ON case_relations(related_case_id,case_id);\nCREATE INDEX events_kind_case ON case_events(case_id,kind,created_at DESC);\nCREATE INDEX cases_deadline ON cases(is_demo,intake,status,due_at);\n", "ALTER TABLE officials ADD COLUMN email TEXT NOT NULL DEFAULT '';\nCREATE UNIQUE INDEX officials_email ON officials(is_demo,email) WHERE email<>'';\nCREATE TABLE runtime_settings(\n is_demo INTEGER PRIMARY KEY CHECK(is_demo IN(0,1)),site_name TEXT NOT NULL DEFAULT 'AICTE',public_url TEXT NOT NULL DEFAULT '',\n support_email TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL DEFAULT 'resend' CHECK(provider IN('resend','sendgrid')),\n sender_name TEXT NOT NULL DEFAULT 'AICTE',recovery_sender TEXT NOT NULL DEFAULT '',updates_sender TEXT NOT NULL DEFAULT '',reply_to TEXT NOT NULL DEFAULT '',\n recovery_enabled INTEGER NOT NULL DEFAULT 0,updates_enabled INTEGER NOT NULL DEFAULT 0,reminders_enabled INTEGER NOT NULL DEFAULT 0,\n daily_email_limit INTEGER NOT NULL DEFAULT 100,reminder_days INTEGER NOT NULL DEFAULT 3,session_hours INTEGER NOT NULL DEFAULT 8,\n updated_at TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES officials(id)\n);\nCREATE TABLE secret_store(is_demo INTEGER NOT NULL,name TEXT NOT NULL,ciphertext TEXT NOT NULL,last_four TEXT NOT NULL,updated_at TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES officials(id),PRIMARY KEY(is_demo,name));\nCREATE TABLE admin_audit(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES officials(id),action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL,is_demo INTEGER NOT NULL);\nCREATE INDEX admin_audit_scope ON admin_audit(is_demo,created_at DESC);\nCREATE TRIGGER admin_audit_immutable_update BEFORE UPDATE ON admin_audit BEGIN SELECT RAISE(ABORT,'Audit history is append-only');END;\nCREATE TRIGGER admin_audit_immutable_delete BEFORE DELETE ON admin_audit BEGIN SELECT RAISE(ABORT,'Audit history is append-only');END;\nCREATE TABLE password_resets(token_hash TEXT PRIMARY KEY,official_id TEXT NOT NULL REFERENCES officials(id),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);\nCREATE INDEX password_resets_official ON password_resets(official_id,expires_at);\nCREATE TABLE recovery_usage(official_id TEXT NOT NULL REFERENCES officials(id),day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(official_id,day));\nCREATE TABLE mail_daily(day TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0);\nCREATE TABLE notification_outbox(id TEXT PRIMARY KEY,recipient_id TEXT NOT NULL REFERENCES officials(id),case_id TEXT REFERENCES cases(id),event_id TEXT REFERENCES case_events(id),kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);\nCREATE INDEX notification_pending ON notification_outbox(status,created_at);\nCREATE TRIGGER case_event_mail AFTER INSERT ON case_events WHEN NEW.kind<>'comment' BEGIN\n INSERT OR IGNORE INTO notification_outbox(id,recipient_id,case_id,event_id,kind,created_at,updated_at)\n SELECT 'mail-'||NEW.id,c.assigned_to,c.id,NEW.id,'update',NEW.created_at,NEW.created_at\n FROM cases c JOIN officials o ON o.id=c.assigned_to JOIN runtime_settings r ON r.is_demo=0\n WHERE c.id=NEW.case_id AND c.is_demo=0 AND o.active=1 AND o.email<>'' AND r.updates_enabled=1;\nEND;\n\nCREATE TABLE production_bootstrap (id INTEGER PRIMARY KEY CHECK(id=1), completed_at TEXT NOT NULL);\n", "ALTER TABLE officials ADD COLUMN report_scope TEXT NOT NULL DEFAULT 'personal' CHECK(report_scope IN('personal','team','bureau'));\nUPDATE officials SET report_scope='team' WHERE role='manager';\nDELETE FROM sessions WHERE official_id='0000' OR portal='it';\nCREATE TABLE app_schema(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);\nINSERT INTO app_schema VALUES(9,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "CREATE TABLE tags_scoped(code TEXT NOT NULL,label TEXT NOT NULL,group_name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL DEFAULT 'custom',is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)),PRIMARY KEY(code,is_demo));\nINSERT INTO tags_scoped(code,label,group_name,active,source,is_demo) SELECT code,label,group_name,active,source,0 FROM tags;\nINSERT INTO tags_scoped(code,label,group_name,active,source,is_demo) SELECT code,label,group_name,active,source,1 FROM tags;\nDROP TABLE tags;\nALTER TABLE tags_scoped RENAME TO tags;\nCREATE INDEX tags_scope ON tags(is_demo,active,group_name,label);\nCREATE INDEX institutions_prefix_name ON institutions(is_demo,name COLLATE NOCASE);\nCREATE INDEX institutions_prefix_id ON institutions(is_demo,permanent_id COLLATE NOCASE);\nCREATE TABLE case_documents(\n id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id),uploaded_by TEXT NOT NULL REFERENCES officials(id),\n filename TEXT NOT NULL,content_type TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0),sha256 TEXT NOT NULL,object_key TEXT NOT NULL UNIQUE,\n status TEXT NOT NULL CHECK(status IN('uploading','ready','deleting','deleted')),is_demo INTEGER NOT NULL CHECK(is_demo IN(0,1)),created_at TEXT NOT NULL\n);\nCREATE INDEX documents_case ON case_documents(case_id,status,created_at);\nCREATE INDEX documents_dataset ON case_documents(is_demo,status,created_at);\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(10,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "CREATE TABLE case_folders (\n case_id TEXT PRIMARY KEY REFERENCES cases(id),drive_url TEXT NOT NULL,\n updated_by TEXT NOT NULL REFERENCES officials(id),updated_at TEXT NOT NULL\n);\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(11,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "ALTER TABLE institutions ADD COLUMN address TEXT NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN district TEXT NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN postal_code TEXT NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN aishe_code TEXT NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN active INTEGER NOT NULL DEFAULT 1;\nCREATE TABLE institution_accounts(\n id TEXT PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),name TEXT NOT NULL,email TEXT NOT NULL,\n password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,is_demo INTEGER NOT NULL CHECK(is_demo IN(0,1)),created_at TEXT NOT NULL\n);\nCREATE INDEX institution_accounts_scope ON institution_accounts(is_demo,institution_id,active);\nCREATE TABLE institution_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES institution_accounts(id),expires_at INTEGER NOT NULL);\nCREATE INDEX institution_session_account ON institution_sessions(account_id,expires_at);\nCREATE TABLE institution_routing(is_demo INTEGER NOT NULL,bureau TEXT NOT NULL,approver_id TEXT NOT NULL REFERENCES officials(id),PRIMARY KEY(is_demo,bureau));\nALTER TABLE case_folders ADD COLUMN is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN(0,1));\nALTER TABLE cases ADD COLUMN institution_account_id TEXT REFERENCES institution_accounts(id);\nALTER TABLE cases ADD COLUMN cancellation_state TEXT NOT NULL DEFAULT '';\nALTER TABLE cases ADD COLUMN institution_escalation TEXT NOT NULL DEFAULT '';\nCREATE INDEX cases_institution_received ON cases(is_demo,institution_id,received_at,id);\nCREATE TABLE institution_events(\n id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id),account_id TEXT NOT NULL REFERENCES institution_accounts(id),kind TEXT NOT NULL,\n body TEXT NOT NULL,created_at TEXT NOT NULL,actor_name TEXT NOT NULL,rating INTEGER\n);\nCREATE INDEX institution_events_case ON institution_events(case_id,created_at,id);\nCREATE UNIQUE INDEX institution_single_review ON institution_events(case_id,account_id,kind) WHERE kind='review';\nCREATE TRIGGER institution_history_update BEFORE UPDATE ON institution_events BEGIN SELECT RAISE(ABORT,'Institution history is append-only');END;\nCREATE TRIGGER institution_history_delete BEFORE DELETE ON institution_events BEGIN SELECT RAISE(ABORT,'Institution history is append-only');END;\nDROP TRIGGER immutable_events_update;\nALTER TABLE case_events ADD COLUMN actor_name_snapshot TEXT NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN actor_bureau_snapshot TEXT NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN actor_designation_snapshot TEXT NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN case_status_snapshot TEXT NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN case_bureau_snapshot TEXT NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN(0,1));\nUPDATE case_events SET actor_name_snapshot=actor_id,actor_bureau_snapshot='Not recorded',actor_designation_snapshot='Legacy event';\nCREATE TRIGGER immutable_events_update BEFORE UPDATE ON case_events WHEN NOT(\n OLD.actor_name_snapshot='' AND OLD.actor_bureau_snapshot='' AND OLD.actor_designation_snapshot='' AND\n NEW.id=OLD.id AND NEW.case_id=OLD.case_id AND NEW.kind=OLD.kind AND NEW.actor_id=OLD.actor_id AND NEW.body=OLD.body AND NEW.created_at=OLD.created_at AND NEW.is_public=OLD.is_public AND\n NEW.actor_name_snapshot=(SELECT name FROM officials WHERE id=OLD.actor_id) AND NEW.actor_bureau_snapshot=(SELECT bureau FROM officials WHERE id=OLD.actor_id) AND NEW.actor_designation_snapshot=(SELECT designation FROM officials WHERE id=OLD.actor_id) AND\n NEW.case_status_snapshot=(SELECT status FROM cases WHERE id=OLD.case_id) AND NEW.case_bureau_snapshot=(SELECT bureau FROM cases WHERE id=OLD.case_id)\n) BEGIN SELECT RAISE(ABORT,'Case history is append-only');END;\nCREATE TRIGGER event_actor_snapshot AFTER INSERT ON case_events WHEN NEW.actor_name_snapshot='' BEGIN\n UPDATE case_events SET actor_name_snapshot=(SELECT name FROM officials WHERE id=NEW.actor_id),actor_bureau_snapshot=(SELECT bureau FROM officials WHERE id=NEW.actor_id),actor_designation_snapshot=(SELECT designation FROM officials WHERE id=NEW.actor_id),case_status_snapshot=(SELECT status FROM cases WHERE id=NEW.case_id),case_bureau_snapshot=(SELECT bureau FROM cases WHERE id=NEW.case_id) WHERE id=NEW.id;\nEND;\nCREATE TABLE handoff_requests(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id),requester_id TEXT NOT NULL REFERENCES officials(id),target_id TEXT NOT NULL REFERENCES officials(id),source_bureau TEXT NOT NULL,target_bureau TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Awaiting receiving manager',reason TEXT NOT NULL,created_at TEXT NOT NULL,decided_at TEXT,decided_by TEXT REFERENCES officials(id));\nCREATE INDEX handoff_scope ON handoff_requests(target_bureau,status,created_at);\nCREATE UNIQUE INDEX handoff_open ON handoff_requests(case_id) WHERE status='Awaiting receiving manager';\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(12,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "CREATE TABLE case_notices(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id),official_id TEXT NOT NULL REFERENCES officials(id),kind TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT);\nCREATE INDEX notices_official ON case_notices(official_id,created_at DESC,id);\nCREATE INDEX notices_unread ON case_notices(official_id,read_at);\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(13,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "ALTER TABLE case_events ADD COLUMN case_assigned_snapshot TEXT NOT NULL DEFAULT '';\nDROP TRIGGER immutable_events_update;\nDROP TRIGGER event_actor_snapshot;\nCREATE TRIGGER immutable_events_update BEFORE UPDATE ON case_events WHEN NOT(\n OLD.actor_name_snapshot='' AND OLD.actor_bureau_snapshot='' AND OLD.actor_designation_snapshot='' AND\n NEW.id=OLD.id AND NEW.case_id=OLD.case_id AND NEW.kind=OLD.kind AND NEW.actor_id=OLD.actor_id AND NEW.body=OLD.body AND NEW.created_at=OLD.created_at AND NEW.is_public=OLD.is_public AND\n NEW.actor_name_snapshot=(SELECT name FROM officials WHERE id=OLD.actor_id) AND NEW.actor_bureau_snapshot=(SELECT bureau FROM officials WHERE id=OLD.actor_id) AND NEW.actor_designation_snapshot=(SELECT designation FROM officials WHERE id=OLD.actor_id) AND\n NEW.case_assigned_snapshot=(SELECT assigned_to FROM cases WHERE id=OLD.case_id) AND NEW.case_status_snapshot=(SELECT status FROM cases WHERE id=OLD.case_id) AND NEW.case_bureau_snapshot=(SELECT bureau FROM cases WHERE id=OLD.case_id)\n) BEGIN SELECT RAISE(ABORT,'Case history is append-only');END;\nCREATE TRIGGER event_actor_snapshot AFTER INSERT ON case_events WHEN NEW.actor_name_snapshot='' BEGIN\n UPDATE case_events SET case_assigned_snapshot=(SELECT assigned_to FROM cases WHERE id=NEW.case_id),actor_name_snapshot=(SELECT name FROM officials WHERE id=NEW.actor_id),actor_bureau_snapshot=(SELECT bureau FROM officials WHERE id=NEW.actor_id),actor_designation_snapshot=(SELECT designation FROM officials WHERE id=NEW.actor_id),case_status_snapshot=(SELECT status FROM cases WHERE id=NEW.case_id),case_bureau_snapshot=(SELECT bureau FROM cases WHERE id=NEW.case_id) WHERE id=NEW.id;\nEND;\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(14,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n", "CREATE TABLE institution_password_resets(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES institution_accounts(id),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);\nCREATE INDEX institution_resets_account ON institution_password_resets(account_id,expires_at);\nCREATE TABLE institution_recovery_usage(account_id TEXT NOT NULL REFERENCES institution_accounts(id),day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,day));\nCREATE INDEX event_responsible_time ON case_events(case_assigned_snapshot,kind,created_at);\nCREATE INDEX event_actor_time ON case_events(actor_id,kind,created_at);\nCREATE INDEX event_bureau_time ON case_events(case_bureau_snapshot,kind,created_at);\nDELETE FROM app_schema;\nINSERT INTO app_schema VALUES(15,strftime('%Y-%m-%dT%H:%M:%fZ','now'));\n"];
export const postgresSchema = "-- AICTED PostgreSQL 16+ live application schema, version 15.\nBEGIN;\n-- Compatible application schema. Connection registry and IT recovery remain in the original D1.\n\nCREATE TABLE officials (\n id TEXT COLLATE \"C\" PRIMARY KEY,name TEXT COLLATE \"C\" NOT NULL,designation TEXT COLLATE \"C\" NOT NULL,bureau TEXT COLLATE \"C\" NOT NULL,\n role TEXT COLLATE \"C\" NOT NULL CHECK(role IN('official','manager','it')),manager_id TEXT COLLATE \"C\" REFERENCES officials(id),\n is_demo SMALLINT NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)),active SMALLINT NOT NULL DEFAULT 1 CHECK(active IN(0,1)),\n password_hash TEXT COLLATE \"C\",password_salt TEXT COLLATE \"C\",report_scope TEXT COLLATE \"C\" NOT NULL DEFAULT 'personal' CHECK(report_scope IN('personal','team','bureau')),email TEXT COLLATE \"C\" NOT NULL DEFAULT ''\n);\nCREATE INDEX officials_manager ON officials(manager_id,is_demo);\nCREATE INDEX officials_directory_fts ON officials USING GIN(to_tsvector('simple',name || ' ' || id || ' ' || designation || ' ' || bureau));\nCREATE TABLE sessions(token_hash TEXT COLLATE \"C\" PRIMARY KEY,official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),expires_at BIGINT NOT NULL,portal TEXT COLLATE \"C\" NOT NULL DEFAULT 'official' CHECK(portal IN('official','it')));\nCREATE INDEX sessions_expiry ON sessions(expires_at);\nCREATE INDEX sessions_official ON sessions(official_id,expires_at);\nCREATE TABLE institutions(id TEXT COLLATE \"C\" PRIMARY KEY,name TEXT COLLATE \"C\" NOT NULL,permanent_id TEXT COLLATE \"C\" NOT NULL UNIQUE,city TEXT COLLATE \"C\" NOT NULL,state TEXT COLLATE \"C\" NOT NULL,region TEXT COLLATE \"C\" NOT NULL,is_demo SMALLINT NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)));\nCREATE INDEX institution_search ON institutions(is_demo,name);\nCREATE TABLE tags(code TEXT COLLATE \"C\" NOT NULL,label TEXT COLLATE \"C\" NOT NULL,group_name TEXT COLLATE \"C\" NOT NULL,active SMALLINT NOT NULL DEFAULT 1,source TEXT COLLATE \"C\" NOT NULL DEFAULT 'reference',is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)),PRIMARY KEY(code,is_demo));\nCREATE TABLE cases(\n id TEXT COLLATE \"C\" PRIMARY KEY,subject TEXT COLLATE \"C\" NOT NULL,institution_id TEXT COLLATE \"C\" NOT NULL REFERENCES institutions(id),bureau TEXT COLLATE \"C\" NOT NULL,\n assigned_to TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),created_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),\n status TEXT COLLATE \"C\" NOT NULL CHECK(status IN('Pending','Under process','Awaiting information','Disposed')),\n intake TEXT COLLATE \"C\" NOT NULL CHECK(intake IN('Submitted','Approved','Returned','Rejected')),\n escalated SMALLINT NOT NULL DEFAULT 0 CHECK(escalated IN(0,1)),priority TEXT COLLATE \"C\" NOT NULL DEFAULT 'Routine',\n tags TEXT COLLATE \"C\" NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(tags::jsonb)='array'),description TEXT COLLATE \"C\" NOT NULL,next_action TEXT COLLATE \"C\" NOT NULL,\n received_at TEXT COLLATE \"C\" NOT NULL,due_at TEXT COLLATE \"C\" NOT NULL,updated_at TEXT COLLATE \"C\" NOT NULL,\n is_demo SMALLINT NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)),approval_reason TEXT COLLATE \"C\" NOT NULL DEFAULT ''\n);\nCREATE INDEX cases_assigned ON cases(is_demo,assigned_to,intake,updated_at DESC,id);\nCREATE INDEX cases_institution ON cases(is_demo,institution_id,intake,status);\nCREATE INDEX cases_created ON cases(is_demo,created_by,intake);\nCREATE INDEX cases_bureau ON cases(is_demo,bureau,intake,updated_at DESC);\nCREATE INDEX cases_tags ON cases USING GIN((tags::jsonb));\nCREATE TABLE case_events(id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),kind TEXT COLLATE \"C\" NOT NULL,actor_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),body TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL);\nCREATE INDEX events_case ON case_events(case_id,created_at,id);\nCREATE OR REPLACE FUNCTION immutable_case_events() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Case history is append-only'; END; $$;\nCREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON case_events FOR EACH ROW EXECUTE FUNCTION immutable_case_events();\nCREATE TABLE case_grants(case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),granted_at TEXT COLLATE \"C\" NOT NULL,revoked_at TEXT COLLATE \"C\",PRIMARY KEY(case_id,official_id));\nCREATE INDEX grants_official ON case_grants(official_id,revoked_at,case_id);\nCREATE TABLE coordination_requests(id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),requester_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),target_official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),target_bureau TEXT COLLATE \"C\" NOT NULL,status TEXT COLLATE \"C\" NOT NULL CHECK(status IN('Awaiting manager','Awaiting Bureau','Approved','Rejected','Revoked')),reason TEXT COLLATE \"C\" NOT NULL,manager_approved_at TEXT COLLATE \"C\",bureau_approved_at TEXT COLLATE \"C\",created_at TEXT COLLATE \"C\" NOT NULL);\nCREATE INDEX coordination_case ON coordination_requests(case_id,created_at);\nCREATE INDEX coordination_target ON coordination_requests(target_official_id,status);\nCREATE UNIQUE INDEX coordination_open ON coordination_requests(case_id,target_official_id) WHERE status IN('Awaiting manager','Awaiting Bureau','Approved');\nCREATE TABLE messages(id TEXT COLLATE \"C\" PRIMARY KEY,sender_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),recipient_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),case_id TEXT COLLATE \"C\" REFERENCES cases(id),body TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL,read_at TEXT COLLATE \"C\",is_demo SMALLINT NOT NULL DEFAULT 0 CHECK(is_demo IN(0,1)));\nCREATE INDEX messages_recipient ON messages(is_demo,recipient_id,created_at DESC);\nCREATE INDEX messages_sender ON messages(is_demo,sender_id,created_at DESC);\nCREATE TABLE workspace_settings(is_demo SMALLINT PRIMARY KEY CHECK(is_demo IN(0,1)),support_email TEXT COLLATE \"C\" NOT NULL DEFAULT '',sender_email TEXT COLLATE \"C\" NOT NULL DEFAULT '',updated_at TEXT COLLATE \"C\" NOT NULL,updated_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id));\nCREATE TABLE migration_settings(source TEXT COLLATE \"C\" NOT NULL DEFAULT 'postgres' CHECK(source IN('d1','postgres')),d1_database_id TEXT COLLATE \"C\" NOT NULL DEFAULT '',is_demo SMALLINT PRIMARY KEY CHECK(is_demo IN(0,1)),host TEXT COLLATE \"C\" NOT NULL DEFAULT '',port INTEGER NOT NULL DEFAULT 5432 CHECK(port BETWEEN 1 AND 65535),database_name TEXT COLLATE \"C\" NOT NULL DEFAULT '',username TEXT COLLATE \"C\" NOT NULL DEFAULT '',ssl_mode TEXT COLLATE \"C\" NOT NULL DEFAULT 'verify-full',updated_at TEXT COLLATE \"C\" NOT NULL,updated_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id));\nCREATE TABLE tag_cache(cache_key TEXT COLLATE \"C\" PRIMARY KEY,suggestions TEXT COLLATE \"C\" NOT NULL,expires_at BIGINT NOT NULL);\nCREATE INDEX tag_cache_expiry ON tag_cache(expires_at);\nCREATE TABLE inference_usage(official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),day TEXT COLLATE \"C\" NOT NULL,calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(official_id,day));\n\n\nCREATE UNIQUE INDEX officials_email ON officials(is_demo,email) WHERE email<>'';\nCREATE TABLE org_units(code TEXT COLLATE \"C\" PRIMARY KEY,name TEXT COLLATE \"C\" NOT NULL,unit_type TEXT COLLATE \"C\" NOT NULL,active SMALLINT NOT NULL DEFAULT 1,verification TEXT COLLATE \"C\" NOT NULL DEFAULT 'unverified',source TEXT COLLATE \"C\" NOT NULL DEFAULT 'Reference/AICTE_Dashboard_Reference_Spec.md');\n\nCREATE TABLE case_relations (\n case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),related_case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),\n kind TEXT COLLATE \"C\" NOT NULL CHECK(kind IN('Related','Duplicate','Unrelated')),reason TEXT COLLATE \"C\" NOT NULL,\n created_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),created_at TEXT COLLATE \"C\" NOT NULL,\n PRIMARY KEY(case_id,related_case_id),CHECK(case_id<related_case_id)\n);\nCREATE INDEX relations_other ON case_relations(related_case_id,case_id);\nCREATE INDEX events_kind_case ON case_events(case_id,kind,created_at DESC);\nCREATE INDEX cases_deadline ON cases(is_demo,intake,status,due_at);\n\nCREATE TABLE runtime_settings(\n is_demo INTEGER PRIMARY KEY CHECK(is_demo IN(0,1)),site_name TEXT COLLATE \"C\" NOT NULL DEFAULT 'AICTE',public_url TEXT COLLATE \"C\" NOT NULL DEFAULT '',\n support_email TEXT COLLATE \"C\" NOT NULL DEFAULT '',provider TEXT COLLATE \"C\" NOT NULL DEFAULT 'resend' CHECK(provider IN('resend','sendgrid')),\n sender_name TEXT COLLATE \"C\" NOT NULL DEFAULT 'AICTE',recovery_sender TEXT COLLATE \"C\" NOT NULL DEFAULT '',updates_sender TEXT COLLATE \"C\" NOT NULL DEFAULT '',reply_to TEXT COLLATE \"C\" NOT NULL DEFAULT '',\n recovery_enabled INTEGER NOT NULL DEFAULT 0,updates_enabled INTEGER NOT NULL DEFAULT 0,reminders_enabled INTEGER NOT NULL DEFAULT 0,\n daily_email_limit INTEGER NOT NULL DEFAULT 100,reminder_days INTEGER NOT NULL DEFAULT 3,session_hours INTEGER NOT NULL DEFAULT 8,\n updated_at TEXT COLLATE \"C\" NOT NULL,updated_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id)\n);\nCREATE TABLE secret_store(is_demo INTEGER NOT NULL,name TEXT COLLATE \"C\" NOT NULL,ciphertext TEXT COLLATE \"C\" NOT NULL,last_four TEXT COLLATE \"C\" NOT NULL,updated_at TEXT COLLATE \"C\" NOT NULL,updated_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),PRIMARY KEY(is_demo,name));\nCREATE TABLE admin_audit(id TEXT COLLATE \"C\" PRIMARY KEY,actor_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),action TEXT COLLATE \"C\" NOT NULL,detail TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL,is_demo INTEGER NOT NULL);\nCREATE INDEX admin_audit_scope ON admin_audit(is_demo,created_at DESC);\nCREATE OR REPLACE FUNCTION immutable_admin_audit() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit history is append-only'; END; $$;\nCREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON admin_audit FOR EACH ROW EXECUTE FUNCTION immutable_admin_audit();\nCREATE TABLE password_resets(token_hash TEXT COLLATE \"C\" PRIMARY KEY,official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);\nCREATE INDEX password_resets_official ON password_resets(official_id,expires_at);\nCREATE TABLE recovery_usage(official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),day TEXT COLLATE \"C\" NOT NULL,calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(official_id,day));\nCREATE TABLE mail_daily(day TEXT COLLATE \"C\" PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0);\nCREATE TABLE notification_outbox(id TEXT COLLATE \"C\" PRIMARY KEY,recipient_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),case_id TEXT COLLATE \"C\" REFERENCES cases(id),event_id TEXT COLLATE \"C\" REFERENCES case_events(id),kind TEXT COLLATE \"C\" NOT NULL,status TEXT COLLATE \"C\" NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT COLLATE \"C\" NOT NULL DEFAULT '',created_at TEXT COLLATE \"C\" NOT NULL,updated_at TEXT COLLATE \"C\" NOT NULL);\nCREATE INDEX notification_pending ON notification_outbox(status,created_at);\nCREATE TABLE production_bootstrap (id INTEGER PRIMARY KEY CHECK(id=1), completed_at TEXT COLLATE \"C\" NOT NULL);\n\n\n\nCREATE OR REPLACE FUNCTION json_each(input TEXT) RETURNS TABLE(value TEXT) LANGUAGE SQL IMMUTABLE AS $$ SELECT jsonb_array_elements_text(input::jsonb); $$;\nCREATE OR REPLACE FUNCTION min(a TEXT,b TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE AS $$ SELECT LEAST(a,b); $$;\nCREATE OR REPLACE FUNCTION max(a TEXT,b TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE AS $$ SELECT GREATEST(a,b); $$;\nCREATE INDEX tags_scope ON tags(is_demo,active,group_name,label);\nCREATE INDEX institutions_prefix_name ON institutions(is_demo,lower(name));\nCREATE INDEX institutions_prefix_id ON institutions(is_demo,lower(permanent_id));\nCREATE TABLE case_documents(\n id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),\n uploaded_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),filename TEXT COLLATE \"C\" NOT NULL,\n content_type TEXT COLLATE \"C\" NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0),sha256 TEXT COLLATE \"C\" NOT NULL,\n object_key TEXT COLLATE \"C\" NOT NULL UNIQUE,status TEXT COLLATE \"C\" NOT NULL CHECK(status IN('uploading','ready','deleting','deleted')),\n is_demo INTEGER NOT NULL CHECK(is_demo IN(0,1)),created_at TEXT COLLATE \"C\" NOT NULL\n);\nCREATE INDEX documents_case ON case_documents(case_id,status,created_at);\nCREATE INDEX documents_dataset ON case_documents(is_demo,status,created_at);\nCREATE TABLE case_folders(case_id TEXT COLLATE \"C\" PRIMARY KEY REFERENCES cases(id),drive_url TEXT COLLATE \"C\" NOT NULL,updated_by TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),updated_at TEXT COLLATE \"C\" NOT NULL);\nCREATE TABLE app_schema(version INTEGER PRIMARY KEY,applied_at TEXT COLLATE \"C\" NOT NULL);\nINSERT INTO app_schema VALUES(15,to_char(now() at time zone 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"'));\nCREATE OR REPLACE FUNCTION enqueue_case_mail() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN\n INSERT INTO notification_outbox(id,recipient_id,case_id,event_id,kind,created_at,updated_at)\n SELECT 'mail-'||NEW.id,c.assigned_to,c.id,NEW.id,'update',NEW.created_at,NEW.created_at\n FROM cases c JOIN officials o ON o.id=c.assigned_to JOIN runtime_settings r ON r.is_demo=0\n WHERE c.id=NEW.case_id AND c.is_demo=0 AND o.active=1 AND o.email<>'' AND r.updates_enabled=1 AND NEW.kind<>'comment'\n ON CONFLICT DO NOTHING;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER case_event_mail AFTER INSERT ON case_events FOR EACH ROW EXECUTE FUNCTION enqueue_case_mail();\n\nALTER TABLE institutions ADD COLUMN address TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN district TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN postal_code TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN aishe_code TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE institutions ADD COLUMN active INTEGER NOT NULL DEFAULT 1;\nCREATE TABLE institution_accounts(\n id TEXT COLLATE \"C\" PRIMARY KEY,institution_id TEXT COLLATE \"C\" NOT NULL REFERENCES institutions(id),name TEXT COLLATE \"C\" NOT NULL,email TEXT COLLATE \"C\" NOT NULL,\n password_hash TEXT COLLATE \"C\" NOT NULL,password_salt TEXT COLLATE \"C\" NOT NULL,active INTEGER NOT NULL DEFAULT 1,is_demo INTEGER NOT NULL CHECK(is_demo IN(0,1)),created_at TEXT COLLATE \"C\" NOT NULL\n);\nCREATE INDEX institution_accounts_scope ON institution_accounts(is_demo,institution_id,active);\nCREATE TABLE institution_sessions(token_hash TEXT COLLATE \"C\" PRIMARY KEY,account_id TEXT COLLATE \"C\" NOT NULL REFERENCES institution_accounts(id),expires_at INTEGER NOT NULL);\nCREATE INDEX institution_session_account ON institution_sessions(account_id,expires_at);\nCREATE TABLE institution_routing(is_demo INTEGER NOT NULL,bureau TEXT COLLATE \"C\" NOT NULL,approver_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),PRIMARY KEY(is_demo,bureau));\nALTER TABLE case_folders ADD COLUMN is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN(0,1));\nALTER TABLE cases ADD COLUMN institution_account_id TEXT COLLATE \"C\" REFERENCES institution_accounts(id);\nALTER TABLE cases ADD COLUMN cancellation_state TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE cases ADD COLUMN institution_escalation TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nCREATE INDEX cases_institution_received ON cases(is_demo,institution_id,received_at,id);\nCREATE TABLE institution_events(\n id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),account_id TEXT COLLATE \"C\" NOT NULL REFERENCES institution_accounts(id),kind TEXT COLLATE \"C\" NOT NULL,\n body TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL,actor_name TEXT COLLATE \"C\" NOT NULL,rating INTEGER\n);\nCREATE INDEX institution_events_case ON institution_events(case_id,created_at,id);\nCREATE UNIQUE INDEX institution_single_review ON institution_events(case_id,account_id,kind) WHERE kind='review';\nALTER TABLE case_events ADD COLUMN actor_name_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN actor_bureau_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN actor_designation_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN case_status_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN case_bureau_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nALTER TABLE case_events ADD COLUMN is_public INTEGER NOT NULL DEFAULT 0 CHECK(is_public IN(0,1));\nCREATE TABLE handoff_requests(id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),requester_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),target_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),source_bureau TEXT COLLATE \"C\" NOT NULL,target_bureau TEXT COLLATE \"C\" NOT NULL,status TEXT COLLATE \"C\" NOT NULL DEFAULT 'Awaiting receiving manager',reason TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL,decided_at TEXT COLLATE \"C\",decided_by TEXT COLLATE \"C\" REFERENCES officials(id));\nCREATE INDEX handoff_scope ON handoff_requests(target_bureau,status,created_at);\nCREATE UNIQUE INDEX handoff_open ON handoff_requests(case_id) WHERE status='Awaiting receiving manager';\n\nCREATE OR REPLACE FUNCTION snapshot_case_event() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN\n IF NEW.actor_name_snapshot='' THEN\n SELECT name,bureau,designation INTO NEW.actor_name_snapshot,NEW.actor_bureau_snapshot,NEW.actor_designation_snapshot FROM officials WHERE id=NEW.actor_id;\n SELECT status,bureau INTO NEW.case_status_snapshot,NEW.case_bureau_snapshot FROM cases WHERE id=NEW.case_id;\n END IF; RETURN NEW; END; $$;\nCREATE TRIGGER event_actor_snapshot BEFORE INSERT ON case_events FOR EACH ROW EXECUTE FUNCTION snapshot_case_event();\nCREATE TRIGGER institution_history BEFORE UPDATE OR DELETE ON institution_events FOR EACH ROW EXECUTE FUNCTION immutable_case_events();\n\nCREATE TABLE case_notices(id TEXT COLLATE \"C\" PRIMARY KEY,case_id TEXT COLLATE \"C\" NOT NULL REFERENCES cases(id),official_id TEXT COLLATE \"C\" NOT NULL REFERENCES officials(id),kind TEXT COLLATE \"C\" NOT NULL,body TEXT COLLATE \"C\" NOT NULL,created_at TEXT COLLATE \"C\" NOT NULL,read_at TEXT COLLATE \"C\");\nCREATE INDEX notices_official ON case_notices(official_id,created_at DESC,id);\nCREATE INDEX notices_unread ON case_notices(official_id,read_at);\nALTER TABLE case_events ADD COLUMN case_assigned_snapshot TEXT COLLATE \"C\" NOT NULL DEFAULT '';\nCREATE OR REPLACE FUNCTION snapshot_case_event() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN\n IF NEW.actor_name_snapshot='' THEN\n SELECT name,bureau,designation INTO NEW.actor_name_snapshot,NEW.actor_bureau_snapshot,NEW.actor_designation_snapshot FROM officials WHERE id=NEW.actor_id;\n SELECT status,bureau,assigned_to INTO NEW.case_status_snapshot,NEW.case_bureau_snapshot,NEW.case_assigned_snapshot FROM cases WHERE id=NEW.case_id;\n END IF; RETURN NEW; END; $$;\nCREATE TABLE institution_password_resets(token_hash TEXT COLLATE \"C\" PRIMARY KEY,account_id TEXT COLLATE \"C\" NOT NULL REFERENCES institution_accounts(id),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);\nCREATE INDEX institution_resets_account ON institution_password_resets(account_id,expires_at);\nCREATE TABLE institution_recovery_usage(account_id TEXT COLLATE \"C\" NOT NULL REFERENCES institution_accounts(id),day TEXT COLLATE \"C\" NOT NULL,calls INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(account_id,day));\nCREATE INDEX event_responsible_time ON case_events(case_assigned_snapshot,kind,created_at);\nCREATE INDEX event_actor_time ON case_events(actor_id,kind,created_at);\nCREATE INDEX event_bureau_time ON case_events(case_bureau_snapshot,kind,created_at);\nCOMMIT;\n";
